      "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 400\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\" aria-label=\"Parametric diagram of the card principle\"><rect x=\"112\" y=\"277.6\" width=\"176\" height=\"50.4\" rx=\"0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/><rect x=\"112\" y=\"227.2\" width=\"176\" height=\"50.4\" rx=\"0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/><rect x=\"112\" y=\"176.8\" width=\"176\" height=\"50.4\" rx=\"0\" fill=\"currentColor\" stroke=\"currentColor\" stroke-width=\"2.2\" fill-opacity=\"0.14\" vector-effect=\"non-scaling-stroke\"/><rect x=\"112\" y=\"126.4\" width=\"176\" height=\"50.4\" rx=\"0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/><rect x=\"112\" y=\"76\" width=\"176\" height=\"50.4\" rx=\"0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" opacity=\"0.4\" vector-effect=\"non-scaling-stroke\"/></svg>"
